package text_test

import (
	"testing"

	"github.com/cristianargotti/golaw/internal/checks/text"
)

// The accented letters are spelled by code point so this file carries none.
func TestCommentLanguage(t *testing.T) {
	t.Parallel()
	res := run(t, text.CommentLanguage(), map[string]string{
		"a.go": "package a\n" +
			"// não é usado\n" +
			"// the value of 'não' is quoted\n" +
			"// São Paulo is a city\n" +
			"/* para cada item */\n" +
			" * está pronto\n" +
			"var x = \"pero\" // trailing comments are not read\n",
		"b.md":   "// esto no cuenta\n",
		"gen.go": "// Code generated by x. DO NOT EDIT.\n// esto\npackage g\n",
	})
	if len(res.Findings) != 3 || res.Scope != "1 files" {
		t.Fatalf("findings = %+v, scope %q", res.Findings, res.Scope)
	}
	lines := []int{res.Findings[0].Line, res.Findings[1].Line, res.Findings[2].Line}
	if lines[0] != 2 || lines[1] != 5 || lines[2] != 6 || res.Findings[2].Column != 4 {
		t.Errorf("lines = %v, column %d", lines, res.Findings[2].Column)
	}
	if res.Findings[0].Code != "comment-language" {
		t.Errorf("code = %q", res.Findings[0].Code)
	}
}
